// predictions와 actuals를 dt_local로 조인하고 지표를 결정적으로 계산
const preds = $('Read predictions').all().map(i => i.json);
const acts = $('Read actuals').all().map(i => i.json);
const actMap = new Map(acts.map(a => [String(a.dt_local), a]));
const now = new Date();
const wk = 7 * 24 * 3600 * 1000;

function metrics(rows) {
  let n = 0, hit = 0, sHalf = 0, sRT = 0, sDA = 0;
  const byClass = { BUY_DA: { n: 0, hit: 0 }, NEUTRAL_5050: { n: 0, hit: 0 }, BUY_RT: { n: 0, hit: 0 } };
  let worst = null;
  for (const p of rows) {
    const a = actMap.get(String(p.dt_local));
    if (!a || a.dart === undefined || a.dart === '') continue;
    const dart = Number(a.dart), da = Number(a.da_spp), rt = Number(a.rt_spp);
    const half = (da + rt) / 2;
    let cost, ok;
    if (p.decision === 'BUY_DA') { cost = da; ok = dart < 0; }
    else if (p.decision === 'BUY_RT') { cost = rt; ok = dart > 0; }
    else { cost = half; ok = Math.abs(dart) <= 1; }
    n++; if (ok) hit++;
    sHalf += half - cost; sRT += rt - cost; sDA += da - cost;
    const c = byClass[p.decision] || (byClass[p.decision] = { n: 0, hit: 0 });
    c.n++; if (ok) c.hit++;
    const loss = cost - Math.min(da, rt);
    if (!worst || loss > worst.loss) worst = { dt: p.dt_local, decision: p.decision, dart: dart, loss: Math.round(loss * 100) / 100 };
  }
  return { n, hit_rate: n ? +(hit / n).toFixed(3) : null,
    save_vs_half: n ? +(sHalf / n).toFixed(3) : null,
    save_vs_rt: n ? +(sRT / n).toFixed(3) : null,
    save_vs_da: n ? +(sDA / n).toFixed(3) : null,
    by_class: Object.fromEntries(Object.entries(byClass).map(([k, v]) => [k, { n: v.n, hit: v.n ? +(v.hit / v.n).toFixed(3) : null }])),
    worst_hour: worst };
}

const last7 = preds.filter(p => (now - new Date(p.dt_local)) < wk && (now - new Date(p.dt_local)) > 0);
const m7 = metrics(last7);
const mAll = metrics(preds);
return [{ json: { week_ending: now.toISOString().slice(0, 10), last7: m7, cumulative: mAll } }];

